const computeTransportFiles={"cpu_and_wall.py": "\"\"\"Measure actual local CPU and elapsed time; no VM, cgroup limit or capacity benchmark.\"\"\"\nfrom concurrent.futures import ThreadPoolExecutor\nimport json\nimport os\nimport platform\nfrom threading import Barrier, Event\nimport time\n\n\ndef burn_thread_cpu(seconds):\n    started = time.thread_time()\n    value = 1\n    while time.thread_time()-started < seconds:\n        for _ in range(200):\n            value = (value*1664525+1013904223) & 0xffffffff\n    return {\"thread_cpu_seconds\": time.thread_time()-started, \"checksum\": value}\n\n\ndef measure(action):\n    wall, cpu = time.perf_counter(), time.process_time()\n    detail = action()\n    return {\"elapsed_seconds\": time.perf_counter()-wall,\n            \"process_cpu_seconds\": time.process_time()-cpu, \"detail\": detail}\n\n\ndef paired_threads():\n    gate = Barrier(2)\n    def worker():\n        gate.wait(timeout=5)\n        return burn_thread_cpu(.10)\n    with ThreadPoolExecutor(max_workers=2) as pool:\n        jobs = [pool.submit(worker) for _ in range(2)]\n        return [job.result(timeout=10) for job in jobs]\n\n\ndef main():\n    cases = {\n        \"one_cpu_phase\": measure(lambda: burn_thread_cpu(.10)),\n        \"one_wait_phase\": measure(lambda: Event().wait(.12)),\n        \"two_cpu_threads\": measure(paired_threads),\n    }\n    assert cases[\"one_cpu_phase\"][\"detail\"][\"thread_cpu_seconds\"] >= .10\n    assert cases[\"one_wait_phase\"][\"elapsed_seconds\"] >= .12\n    assert all(row[\"thread_cpu_seconds\"] >= .10 for row in cases[\"two_cpu_threads\"][\"detail\"])\n    for row in cases.values():\n        assert row[\"elapsed_seconds\"] > 0 and row[\"process_cpu_seconds\"] >= 0\n    print(json.dumps({\"python\": platform.python_version(), \"system\": platform.system(),\n                      \"logical_cpu_count_hint\": os.cpu_count(), \"cases\": cases,\n                      \"scope\": \"actual_local_CPU_and_wait_measurements_not_VM_quota_or_throughput_benchmark\",\n                      \"limits\": [\"CPU targets are workload stopping conditions, not a simulated cgroup budget\",\n                                 \"two threads share this process; GIL/build/native-code/platform affect parallel execution\",\n                                 \"logical CPU count does not measure guaranteed capacity or identify physical core ownership\",\n                                 \"actual timings vary; compare accounting categories, not speedup ratios\"]}, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n", "socket_backpressure.py": "\"\"\"Actual bounded loopback send/receive backpressure; no packet trace or congestion-control benchmark.\"\"\"\nimport hashlib\nimport json\nimport platform\nimport selectors\nimport socket\nfrom threading import Event, Thread\nimport time\n\n\ndef main():\n    payload = b\"infra-local-byte-stream\\n\" * 32768\n    allow_read = Event()\n    received = {}\n    errors = []\n    with socket.socket() as listener:\n        listener.setsockopt(socket.SOL_SOCKET, socket.SO_RCVBUF, 16384)\n        listener.bind((\"127.0.0.1\", 0))\n        listener.listen(1)\n        listener.settimeout(5)\n        def receiver():\n            try:\n                with listener.accept()[0] as connection:\n                    connection.settimeout(8)\n                    received[\"receive_buffer_setting\"] = connection.getsockopt(socket.SOL_SOCKET, socket.SO_RCVBUF)\n                    if not allow_read.wait(5):\n                        raise TimeoutError(\"sender_never_released_reader\")\n                    digest = hashlib.sha256()\n                    total = 0\n                    while True:\n                        block = connection.recv(16384)\n                        if not block:\n                            break\n                        total += len(block)\n                        digest.update(block)\n                    received.update(bytes=total, sha256=digest.hexdigest(), saw_eof=True)\n                    connection.sendall(json.dumps({\"bytes\": total, \"sha256\": digest.hexdigest()}).encode())\n            except BaseException as error:\n                errors.append(type(error).__name__+\": \"+str(error))\n        thread = Thread(target=receiver, daemon=True)\n        thread.start()\n        try:\n            with socket.create_connection(listener.getsockname(), timeout=5) as sender:\n                sender.setsockopt(socket.SOL_SOCKET, socket.SO_SNDBUF, 16384)\n                send_buffer = sender.getsockopt(socket.SOL_SOCKET, socket.SO_SNDBUF)\n                sender.setblocking(False)\n                offset, calls, short_writes = 0, 0, 0\n                blocked_before_read = False\n                while offset < len(payload):\n                    part = memoryview(payload)[offset:offset+16384]\n                    try:\n                        count = sender.send(part)\n                    except BlockingIOError:\n                        blocked_before_read = True\n                        break\n                    assert count > 0\n                    calls += 1\n                    short_writes += count < len(part)\n                    offset += count\n                accepted_before_read = offset\n                allow_read.set()  # The application reader begins only after this controlled boundary.\n                deadline = time.monotonic()+8\n                with selectors.DefaultSelector() as selector:\n                    selector.register(sender, selectors.EVENT_WRITE)\n                    while offset < len(payload):\n                        if time.monotonic() >= deadline:\n                            raise TimeoutError(\"bounded_transfer_deadline\")\n                        if not selector.select(.1):\n                            continue\n                        part = memoryview(payload)[offset:offset+16384]\n                        try:\n                            count = sender.send(part)\n                        except BlockingIOError:\n                            continue\n                        assert count > 0\n                        calls += 1\n                        short_writes += count < len(part)\n                        offset += count\n                sender.setblocking(True)\n                sender.settimeout(8)\n                sender.shutdown(socket.SHUT_WR)\n                reply = bytearray()\n                while True:\n                    block = sender.recv(1024)\n                    if not block:\n                        break\n                    reply.extend(block)\n                    if len(reply) > 1024:\n                        raise ValueError(\"unexpected_fixture_reply\")\n                receipt = json.loads(reply)\n        finally:\n            allow_read.set()\n            thread.join(10)\n        assert not thread.is_alive() and not errors, errors\n    expected = hashlib.sha256(payload).hexdigest()\n    assert offset == received[\"bytes\"] == receipt[\"bytes\"] == len(payload)\n    assert expected == received[\"sha256\"] == receipt[\"sha256\"]\n    assert received[\"saw_eof\"]\n    print(json.dumps({\"python\": platform.python_version(), \"system\": platform.system(),\n                      \"payload_bytes\": len(payload), \"send_buffer_setting\": send_buffer,\n                      \"receive_buffer_setting\": received[\"receive_buffer_setting\"],\n                      \"blocked_before_application_read\": blocked_before_read,\n                      \"accepted_before_application_read\": accepted_before_read,\n                      \"successful_send_calls\": calls, \"short_writes_observed\": short_writes,\n                      \"received_bytes\": receipt[\"bytes\"], \"sha256\": expected,\n                      \"read_reply_after_write_shutdown\": True,\n                      \"scope\": \"actual_loopback_nonblocking_send_and_application_drain_not_packet_or_cwnd_measurement\",\n                      \"limits\": [\"send accepted bytes into a local socket path, not proof that receiver application read them\",\n                                 \"paused application may still have bytes received/acknowledged by its kernel\",\n                                 \"buffer settings and partial-write boundaries depend on the OS; cap does not force a block on every stack\",\n                                 \"receiver JSON is this fixture's explicit application receipt, not TCP ACK\"]}, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n"};
const computeTransportValidation={"verified_at_utc": "2026-11-04T17:38:45.641560+00:00", "platform": "macOS-26.2-arm64-arm-64bit", "programs": {"cpu_and_wall.py": {"sha256": "49c6645f47156bf1f78f15f96241dc8e72e63919475483b9604aba568f8e6c6a", "exit_code": 0, "result": {"python": "3.9.6", "system": "Darwin", "logical_cpu_count_hint": 14, "cases": {"one_cpu_phase": {"elapsed_seconds": 0.100034333, "process_cpu_seconds": 0.100016, "detail": {"thread_cpu_seconds": 0.100005834, "checksum": 3490371073}}, "one_wait_phase": {"elapsed_seconds": 0.13008166699999998, "process_cpu_seconds": 8.400000000000074e-05, "detail": false}, "two_cpu_threads": {"elapsed_seconds": 0.200274958, "process_cpu_seconds": 0.20049599999999998, "detail": [{"thread_cpu_seconds": 0.100003333, "checksum": 157103905}, {"thread_cpu_seconds": 0.100007583, "checksum": 2092691489}]}}, "scope": "actual_local_CPU_and_wait_measurements_not_VM_quota_or_throughput_benchmark", "limits": ["CPU targets are workload stopping conditions, not a simulated cgroup budget", "two threads share this process; GIL/build/native-code/platform affect parallel execution", "logical CPU count does not measure guaranteed capacity or identify physical core ownership", "actual timings vary; compare accounting categories, not speedup ratios"]}}, "socket_backpressure.py": {"sha256": "3f2ce932450829086c6223b7341c6b2f81bfa3a6d44543167708bea73c08833a", "exit_code": 0, "result": {"python": "3.9.6", "system": "Darwin", "payload_bytes": 786432, "send_buffer_setting": 16384, "receive_buffer_setting": 326640, "blocked_before_application_read": true, "accepted_before_application_read": 16384, "successful_send_calls": 48, "short_writes_observed": 0, "received_bytes": 786432, "sha256": "539d0bfeb36296bab26e2aabccb9dc150ab92b9cc8249dbca7de3609ea95c00e", "read_reply_after_write_shutdown": true, "scope": "actual_loopback_nonblocking_send_and_application_drain_not_packet_or_cwnd_measurement", "limits": ["send accepted bytes into a local socket path, not proof that receiver application read them", "paused application may still have bytes received/acknowledged by its kernel", "buffer settings and partial-write boundaries depend on the OS; cap does not force a block on every stack", "receiver JSON is this fixture's explicit application receipt, not TCP ACK"]}}}};


