// capacity-roofline-observation.js
/* Continue three learning paths through their middle mechanisms and existing executable evidence. */
const capacityRooflineObservationEdits=[];
function reviseSystemWalk(id,index,edit){const a=articleById(id),s=a.sections[index],before=s[1];edit(s);if(s[1]===before)throw Error('Unapplied system walkthrough: '+id+'/'+index);capacityRooflineObservationEdits.push({id,section:index+1});a.updated='2026.11.08';}
function replaceSystemText(s,from,to){if(!s[1].includes(from))throw Error('Missing reviewed bridge: '+from);s[1]=s[1].replace(from,to);}
const capacityForecastCode=`from fractions import Fraction

incoming, old_capacity, delay = 180, 120, 120
backlog = (incoming - old_capacity) * delay
for new_capacity in (160, 180, 200):
    spare = new_capacity - incoming
    if spare < 0:
        result = "继续积压，每秒增加" + str(-spare)
    elif spare == 0:
        result = "只够追平输入，旧积压不减少"
    else:
        result = "再需" + str(Fraction(backlog, spare)) + "秒排空"
    print(new_capacity, "次/秒：", result)`;

